import numpy as np

def logloss_grad(w, X, y):
    p = 1 / (1 + np.exp(-X @ w))
    return X.T @ (p - y) / len(y)

# проверка численным градиентом
def loss(w, X, y):
    p = 1 / (1 + np.exp(-X @ w))
    return -np.mean(y * np.log(p) + (1 - y) * np.log(1 - p))

eps = 1e-6
num = np.array([(loss(w + eps * e, X, y) - loss(w - eps * e, X, y)) / (2 * eps) for e in np.eye(len(w))])
assert np.allclose(num, logloss_grad(w, X, y), atol=1e-6)

def pair_with_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return seen[target - x], i
        seen[x] = i
    return None

assert pair_with_sum([3, 2, 4], 6) == (1, 2)
assert pair_with_sum([3, 3], 6) == (0, 1)
assert pair_with_sum([1, 2], 7) is None

def max_window_sum(a, k):
    if k <= 0 or k > len(a):
        raise ValueError('k вне диапазона')
    s = best = sum(a[:k])
    for i in range(k, len(a)):
        s += a[i] - a[i - k]
        best = max(best, s)
    return best

assert max_window_sum([1, 4, 2, 10, 2, 3, 1, 0, 20], 4) == 24

