import torch
from torch.utils.data import Dataset, DataLoader

class TextDataset(Dataset):
    def __init__(self, texts, labels, tokenizer, max_len=256):
        self.texts, self.labels, self.tok, self.max_len = texts, labels, tokenizer, max_len

    def __len__(self):
        return len(self.texts)

    def __getitem__(self, i):
        ids = self.tok(self.texts[i], truncation=True, max_length=self.max_len)['input_ids']
        return torch.tensor(ids), self.labels[i]

def collate(batch, pad_id=0):
    ids, labels = zip(*batch)
    width = max(len(x) for x in ids)
    input_ids = torch.full((len(ids), width), pad_id)
    mask = torch.zeros((len(ids), width), dtype=torch.long)
    for row, x in enumerate(ids):
        input_ids[row, :len(x)] = x
        mask[row, :len(x)] = 1
    return input_ids, mask, torch.tensor(labels)

train_loader = DataLoader(TextDataset(tr_x, tr_y, tok), batch_size=32, shuffle=True, collate_fn=collate)
val_loader = DataLoader(TextDataset(va_x, va_y, tok), batch_size=64, shuffle=False, collate_fn=collate)

